  ('5202 Series Yellow Jacket Planetary Gear Motor (19.2:1 Ratio, 312 RPM, 3.3 - 5V Encoder)', '5202-0002-0019', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-19-2-1-ratio-312-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1070/images/5261/5202-0002-0019-FTC-Legal__39442__67006.1701992478.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (26.9:1 Ratio, 223 RPM, 3.3 - 5V Encoder)', '5202-0002-0027', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-26-9-1-ratio-223-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1044/images/5101/5202-0002-0027-FTC-Legal__31679__08706.1701992431.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (50.9:1 Ratio, 117 RPM, 3.3 - 5V Encoder)', '5202-0002-0051', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-50-9-1-ratio-117-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1046/images/5118/5202-0002-0051-FTC-Legal__86500__54605.1701992436.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (71.2:1 Ratio, 84 RPM, 3.3 - 5V Encoder)', '5202-0002-0071', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-71-2-1-ratio-84-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1068/images/5234/5202-0002-0071-FTC-Legal__90496__29430.1701992470.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (99.5:1 Ratio, 60 RPM, 3.3 - 5V Encoder)', '5202-0002-0100', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-99-5-1-ratio-60-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1066/images/5206/5202-0002-0100-FTC-Legal__62851__62372.1701992463.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (139:1 Ratio, 43 RPM, 3.3 - 5V Encoder)', '5202-0002-0139', null, 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-139-1-ratio-43-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1062/images/5191/5202-0002-0139-FTC-Legal__16977__79484.1701992458.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (188:1 Ratio, 30 RPM, 3.3 - 5V Encoder)', '5202-0002-0188', 'Please Note: The immense torque generated by this motor and gearing combination is capable of twisting off the steel 6mm D-shaft. For this reason, we advise against stalling this gear motor.', 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-188-1-ratio-30-rpm-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1067/images/5220/5202-0002-0188-FTC-Legal__34997__37054.1701992467.386.513.jpg?c=1', null, 'gobilda'),
  ('5202 Series Yellow Jacket Planetary Gear Motor (3.7:1 Ratio, 24mm Length 6mm D-Shaft, 1620 RPM, ⌀36mm Gearbox, 3.3 - 5V Encoder)', '5202-2402-0003', 'This 3.7:1 ratio gear motor runs at a no-load speed of 1620RPM when 12VDC is applied. Mounted to the back of the 5000 Series Motor driving the gearbox is a quadrature encoder able to run on both 3.3V and 5V. Its bullet connectors are a reliable connection style that allows you to easily reverse polarity to the motor and pass its wires through 14mm holes in goBILDA® channel, even when grommets are installed.', 'goBILDA', null, true, 'https://www.gobilda.com/5202-series-yellow-jacket-planetary-gear-motor-3-7-1-ratio-24mm-length-6mm-d-shaft-1620-rpm-36mm-gearbox-3-3-5v-encoder/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2032/images/14788/5202-2402-0003__23238.1759847367.386.513.jpg?c=1', 'MOTION / Motors / Yellow Jacket Planetary Gear Motors', 'gobilda'),
